'use strict';
const parties={Ap:{name:'Arbeiderpartiet',color:'#df3e46',logo:'ap.png'},H:{name:'Høyre',color:'#2678be',logo:'h.svg'},Sp:{name:'Senterpartiet',color:'#299755',logo:'sp-symbol.png'},FrP:{name:'Fremskrittspartiet',color:'#253c73',logo:'frp.png'},KrF:{name:'Kristelig Folkeparti',color:'#e9ae22',logo:'krf.png'},V:{name:'Venstre',color:'#007d82',logo:'v-symbol.svg'},SV:{name:'Sosialistisk Venstreparti',color:'#be3653',logo:'sv.svg'},R:{name:'Rødt',color:'#a82329',logo:'r.svg'},MDG:{name:'Miljøpartiet De Grønne',color:'#63932d',logo:'mdg.svg'},SOL:{name:'Solrenningslista',color:'#766286'},Andre:{name:'Andre',color:'#8993a3'}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>n.toLocaleString('nb-NO',{minimumFractionDigits:1,maximumFractionDigits:1});
const date=s=>new Date(s+'T12:00:00').toLocaleDateString('nb-NO',{day:'numeric',month:'long',year:'numeric'});
const logo=(p,party='')=>p.logo?`<img class="party-logo ${party==='H'?'party-h':''}" src="assets/logos/${p.logo}" alt="${esc(p.name)}">`:'<span class="local" aria-label="Solrenningslista">SOL</span>';
async function start(){
 const [municipalities,geo,polls]=await Promise.all(['municipalities.json','vestland.geojson','polls.json'].map(async f=>{const r=await fetch('data/'+f);if(!r.ok)throw new Error('Data kunne ikke lastes');return r.json()}));
 const byId=new Map(municipalities.map(m=>[m.id,m]));const layers=new Map(),markers=new Map();let selected='4601';const select=document.querySelector('#municipality');select.innerHTML=municipalities.slice().sort((a,b)=>a.name.localeCompare(b.name,'nb')).map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('');document.querySelector('#poll-count').textContent=Object.keys(polls).length;
 function show(id){const m=byId.get(id);if(!m)return;selected=id;select.value=id;const p=parties[m.party],poll=polls[id];for(const [key,l]of layers)l.setStyle({color:key===id?'#087c83':'#809aa8',weight:key===id?2.8:1,fillColor:parties[byId.get(key).party].color,fillOpacity:key===id?.30:.13});for(const [key,marker]of markers)marker.getElement()?.classList.toggle('selected',key===id);
 const bars=poll?Object.entries(poll.values).map(([party,value])=>{const pp=parties[party],label=party==='H'?'Høyre':party==='R'?'Rødt':party==='V'?'Venstre':party;return `<div class="bar-row" aria-label="${esc(pp.name)}: ${pct(value)} prosent"><span class="bar-label">${label}</span><div class="bar-track" aria-hidden="true"><div class="bar-fill" style="--party:${pp.color};--value:${value/Math.max(...Object.values(poll.values))*100}%"></div></div><span class="bar-value">${pct(value)}</span></div>`}).join(''):'';
 document.querySelector('#detail-content').innerHTML=`<p class="detail-kicker">Vestland · Kommune ${m.id}</p><h2>${esc(m.name)}</h2><div class="mayor"><div class="mayor-logo">${logo(p)}</div><div><small>${m.acting?'Fungerende ordfører':'Ordfører'}</small><p><strong>${esc(m.mayor)}</strong><br>(${esc(p.name)})</p><a class="source" href="${esc(m.source)}" target="_blank" rel="noopener">Kilde til ordfører ↗</a></div></div>${m.note?`<p class="mayor-note">${esc(m.note)}</p>`:''}${poll?`<div class="poll-head"><h3>Siste kommunemåling</h3><span class="tag">2026</span></div><p class="poll-meta">${date(poll.date)}<br>${esc(poll.institute)} for ${esc(poll.client)}</p><div class="chart" role="group" aria-label="Partienes oppslutning i prosent">${bars}</div><p class="chart-note">Oppslutning i prosent · ${poll.sample} spurte<br>Feltperiode: ${esc(poll.fieldwork)}. Målingen har feilmarginer.</p><a class="poll-source" href="${esc(poll.source)}" target="_blank" rel="noopener">Se målingen hos Poll of polls ↗</a>`:`<div class="empty"><div class="empty-symbol" aria-hidden="true">▂ ▅ ▃</div><h3>Ingen måling registrert i 2026</h3><p>Vi fant ingen kommunemåling fra 2026 for ${esc(m.name)} hos Poll of polls ved siste kontroll.</p><a href="https://www.pollofpolls.no/?cmd=Maling&filter=kommune" target="_blank" rel="noopener">Se alle kommunemålinger ↗</a></div>`}`;}
 const map=L.map('map',{zoomControl:false,scrollWheelZoom:!window.matchMedia('(pointer:coarse)').matches,minZoom:6,maxZoom:13,zoomSnap:.25});L.control.zoom({position:'topright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);
 const boundary=L.geoJSON(geo,{style:f=>({color:'#809aa8',weight:1,fillColor:parties[byId.get(f.properties.kommunenummer).party].color,fillOpacity:.13}),onEachFeature:(feature,layer)=>{const id=feature.properties.kommunenummer,m=byId.get(id);layers.set(id,layer);layer.bindTooltip(`<strong>${esc(m.name)}</strong>${esc(m.mayor)} (${esc(parties[m.party].name)})`,{sticky:true,direction:'top'});layer.on({mouseover:()=>show(id),click:()=>show(id)})}}).addTo(map);
 const bounds=boundary.getBounds();function fit(){map.fitBounds(bounds,{padding:[24,25],animate:false})}fit();for(const m of municipalities){const p=parties[m.party];const marker=L.marker([m.point[1],m.point[0]],{icon:L.divIcon({className:'party-marker',html:`<span class="marker-inner">${logo(p)}</span>`,iconSize:[30,30],iconAnchor:[15,15]}),title:`${m.name}: ${m.mayor} (${p.name})`,alt:`${m.name}: ${m.mayor} (${p.name})`,keyboard:true,riseOnHover:true}).addTo(map);marker.bindTooltip(`<strong>${esc(m.name)}</strong>${esc(m.mayor)} (${esc(p.name)})`,{direction:'top',offset:[0,-13]});marker.on({mouseover:()=>show(m.id),click:()=>show(m.id)});marker.getElement()?.addEventListener('focus',()=>show(m.id));markers.set(m.id,marker)}select.addEventListener('change',()=>{show(select.value);const point=byId.get(select.value).point;map.panTo([point[1],point[0]])});document.querySelector('#reset').addEventListener('click',fit);new ResizeObserver(()=>{map.invalidateSize();fit()}).observe(document.querySelector('.map-shell'));document.querySelector('#legend').innerHTML=[...new Set(municipalities.map(m=>m.party))].sort().map(key=>`<span class="legend-item"><i style="--party:${parties[key].color}"></i>${key==='H'?'Høyre':key==='SOL'?'Lokal liste':key}</span>`).join('');show(selected);
}
start().catch(error=>{console.error(error);document.querySelector('#map-error').hidden=false;document.querySelector('#map-error').textContent='Kartet kunne ikke lastes. Prøv å laste siden på nytt.';document.querySelector('#detail-content').innerHTML='<p>Kommuneinformasjonen kunne ikke lastes. Prøv igjen om litt.</p>'});

const electionResults2023={
 '4601':{Ap:[18.5,13],H:[26.5,18],FrP:[10.5,7],SV:[10,7],Sp:[2.3,2],KrF:[3.4,2],V:[5,3],MDG:[5.2,4],R:[4,3],Andre:[14.6,8]},
 '4625':{Ap:[10.7,2],H:[32.6,7],FrP:[33.1,8],SV:[1.8,0],Sp:[1.9,0],KrF:[4.9,1],V:[1,0],MDG:[3.7,1],R:[0,0],Andre:[10.3,2]}
};
const electionLabels={H:'Høyre',R:'Rødt',V:'Venstre'};
function addElectionResult(){const select=document.querySelector('#municipality'),content=document.querySelector('#detail-content'),result=electionResults2023[select?.value];if(!content||!result||content.querySelector('.election-2023'))return;const rows=Object.entries(result).map(([party,[percent,seats]])=>`<li><span><i style="--party:${parties[party].color}"></i>${electionLabels[party]||party}</span><strong>${pct(percent)} % <em>${seats} ${seats===1?'mandat':'mandater'}</em></strong></li>`).join('');const source=content.querySelector('.poll-source');if(source)source.insertAdjacentHTML('afterend',`<section class="election-2023"><h3>Valgresultat 2023</h3><p>Oppslutning og mandater</p><ul>${rows}</ul></section>`)}
const resultObserver=new MutationObserver(addElectionResult);resultObserver.observe(document.querySelector('#detail-content'),{childList:true});document.querySelector('#municipality').addEventListener('change',()=>setTimeout(addElectionResult,0));
const mapStyle=document.createElement('style');mapStyle.textContent='.marker-inner img{width:15px!important;height:15px!important}.marker-inner img[src$="h.svg"]{width:11px!important;height:11px!important}.election-2023{border-top:1px solid var(--border);margin-top:24px;padding-top:20px}.election-2023 h3{font-size:1rem;margin:0}.election-2023>p{font-size:.75rem;color:var(--muted);margin:5px 0 12px}.election-2023 ul{list-style:none;padding:0;margin:0;display:grid;gap:7px}.election-2023 li{display:flex;justify-content:space-between;gap:10px;font-size:.8125rem}.election-2023 li>span{display:flex;align-items:center;gap:7px;color:#37556b}.election-2023 i{display:inline-block;width:8px;height:8px;background:var(--party);border-radius:50%}.election-2023 strong{font-variant-numeric:tabular-nums;white-space:nowrap}.election-2023 em{font-style:normal;color:var(--muted);font-weight:400;font-size:.75rem;margin-left:4px}';document.head.append(mapStyle);
